/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Curve, Line2D, Mul, Point2D, Pow, Sym, fn, mul, pi, pow, rational, symbols } from '../../src';
import { at, sympyStr } from '../sympy-str';

describe("doctests of sympy.geometry.curve", () => {
  it("C.functions", () => {
    const t = new Sym('t');
    expect(sympyStr(Curve([fn('sin', [t]), fn('cos', [t])], [t, rational(0), rational(2)]).functions)).toBe('(sin(t), cos(t))');
  });
  it("C.limits", () => {
    const t = new Sym('t');
    expect(sympyStr(Curve([fn('sin', [t]), fn('cos', [t])], [t, rational(0), rational(2)]).limits)).toBe('(t, 0, 2)');
  });
  it("C.parameter", () => {
    const t = new Sym('t');
    expect(sympyStr(t)).toBe('t');
  });
  it("C.subs(t, 4)", () => {
    const t = new Sym('t');
    expect(sympyStr(Curve([t, pow(t, 2)], [t, rational(0), rational(1)]).subs(t, rational(4)))).toBe('Point2D(4, 16)');
  });
  it("C.arbitrary_point(a)", () => {
    const [t, a] = symbols('t a');
    expect(sympyStr(Curve([t, pow(t, 2)], [t, rational(0), rational(1)]).arbitraryPoint(a))).toBe('Point2D(a, a**2)');
  });
  it("C.ambient_dimension", () => {
    const t = new Sym('t');
    expect(sympyStr(Curve([t, pow(t, 2)], [t, rational(0), rational(2)]).ambientDimension)).toBe('2');
  });
  it("C.arbitrary_point()", () => {
    const s = new Sym('s');
    expect(sympyStr(Curve([mul(2, s), pow(s, 2)], [s, rational(0), rational(2)]).arbitraryPoint())).toBe('Point2D(2*t, t**2)');
  });
  it("C.arbitrary_point(C.parameter)", () => {
    const s = new Sym('s');
    expect(sympyStr(Curve([mul(2, s), pow(s, 2)], [s, rational(0), rational(2)]).arbitraryPoint(s))).toBe('Point2D(2*s, s**2)');
  });
  it("C.arbitrary_point(None)", () => {
    const s = new Sym('s');
    expect(sympyStr(Curve([mul(2, s), pow(s, 2)], [s, rational(0), rational(2)]).arbitraryPoint(null))).toBe('Point2D(2*s, s**2)');
  });
  it("C.arbitrary_point(Symbol('a'))", () => {
    const [s, a] = symbols('s a');
    expect(sympyStr(Curve([mul(2, s), pow(s, 2)], [s, rational(0), rational(2)]).arbitraryPoint(a))).toBe('Point2D(2*a, a**2)');
  });
  it("Curve((t, t**2), (t, 0, 2)).free_symbols", () => {
    expect(sympyStr(new Set())).toBe('set()');
  });
  it("Curve((t, t**2), (t, a, 2)).free_symbols", () => {
    const a = new Sym('a');
    expect(sympyStr(new Set([a]))).toBe('{a}');
  });
  it("C.functions (2)", () => {
    const t = new Sym('t');
    expect(sympyStr(Curve([t, pow(t, 2)], [t, rational(0), rational(2)]).functions)).toBe('(t, t**2)');
  });
  it("Curve((t, t), (t, 0, 1)).length", () => {
    const t = new Sym('t');
    expect(sympyStr(Curve([t, t], [t, rational(0), rational(1)]).length)).toBe('sqrt(2)');
  });
  it("C.limits (2)", () => {
    const t = new Sym('t');
    expect(sympyStr(Curve([t, pow(t, 3)], [t, rational(-2), rational(2)]).limits)).toBe('(t, -2, 2)');
  });
  it("C.parameter (2)", () => {
    const t = new Sym('t');
    expect(sympyStr(t)).toBe('t');
  });
  it("Curve((x, sin(x)), (x, 1, 2)).plot_interval()", () => {
    const x = new Sym('x');
    const v1 = rational(1);
    const v2 = rational(2);
    expect(sympyStr([at(Curve([x, fn('sin', [x])], [x, v1, v2]).plotInterval(), 0), v1, v2])).toBe('[t, 1, 2]');
  });
  it("Curve((x, sin(x)), (x, 1, 2)).plot_interval(s)", () => {
    const s = new Sym('s');
    expect(sympyStr([s, rational(1), rational(2)])).toBe('[s, 1, 2]');
  });
  it("Curve((x, x), (x, 0, 1)).rotate(pi/2)", () => {
    const x = new Sym('x');
    expect(sympyStr(Curve([x, x], [x, rational(0), rational(1)]).rotate(mul(rational(1, 2), pi)))).toBe('Curve((-x, x), (x, 0, 1))');
  });
  it("Curve((x, x), (x, 0, 1)).scale(2)", () => {
    const x = new Sym('x');
    expect(sympyStr(Curve([x, x], [x, rational(0), rational(1)]).scale(2))).toBe('Curve((2*x, x), (x, 0, 1))');
  });
  it("Curve((x, x), (x, 0, 1)).translate(1, 2)", () => {
    const x = new Sym('x');
    expect(sympyStr(Curve([x, x], [x, rational(0), rational(1)]).translate(1, 2))).toBe('Curve((x + 1, x + 2), (x, 0, 1))');
  });
});

